#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <nb.h>

/* The same synthetic prices and the same running-sum moving average, in C. */
int main() {
    int n = (int)nb_get_int("fp_ticks", 1000000);
    int w = (int)nb_get_int("fp_window", 50);
    double *p = malloc(sizeof(double) * n);
    double *ma = malloc(sizeof(double) * n);
    for (long long i = 0; i < n; i++)
        p[i] = 100 + 10 * sin(i / 500.0) + 3 * sin(i / 37.7) + ((i * 2654435761LL) % 1000) / 1000.0 - 0.5;

    int repeats = 10;                   /* the clock is coarse, so time several passes */
    clock_t t0 = clock();
    for (int r = 0; r < repeats; r++) {
        double s = 0;
        for (int k = 0; k < w; k++) s += p[k];
        ma[w - 1] = s / w;
        for (int k = w; k < n; k++) {
            s += p[k] - p[k - w];       /* add the newest, drop the oldest */
            ma[k] = s / w;
        }
    }
    double seconds = (double)(clock() - t0) / CLOCKS_PER_SEC / repeats;

    double check = 0;
    for (int k = w - 1; k < n; k++) check += ma[k];
    printf("C, running sum: %.2f ns per tick (%d ticks, window %d, averaged over %d passes)\n",
           seconds / n * 1e9, n, w, repeats);
    printf("sum of all the averages: %.6f\n", check);
    printf("__NB_SET__ {\"key\":\"fp_c\",\"value\":{\"ns\":%.4f,\"ticks\":%d,\"check\":%.6f}}\n", seconds / n * 1e9, n, check);
    free(p); free(ma);
    return 0;
}

// Put the five methods side by side, per tick, and check C against numpy.
const py = nb.get('fp_py'), c = nb.get('fp_c'), sample = nb.get('fp_sample');
if (!py) return 'Run the Python cell first.';

const rows = py.results.map(r => ({ method: r.method, ns: r.ns, lang: r.method.startsWith('numpy') ? 'numpy' : 'pure Python' }));
if (c) rows.push({ method: 'C, running sum', ns: c.ns, lang: 'C' });
const slowest = Math.max(...rows.map(r => r.ns));
console.log('method                   ns per tick   times faster than the naive loop');
for (const r of rows) console.log(r.method.padEnd(24) + r.ns.toFixed(1).padStart(12) + (slowest / r.ns).toFixed(0).padStart(14) + 'x');
if (c && c.ticks === py.n) {
  console.log('\nC and numpy agree: sums of all the averages differ by ' +
    (Math.abs(c.check - py.check) / py.check).toExponential(1) + ' of the total');
} else if (c) {
  console.log('\nRun the C cell again: it used a different number of ticks from the Python cell.');
}

const bars = {
  width: 700, height: 200,
  title: 'Nanoseconds per tick (log scale): shorter is faster',
  data: { values: rows },
  mark: 'bar',
  encoding: {
    y: { field: 'method', type: 'nominal', sort: '-x', title: null },
    x: { field: 'ns', type: 'quantitative', scale: { type: 'log' }, title: 'ns per tick' },
    x2: { datum: 1 },          // a log-scale bar needs somewhere to start
    color: { field: 'lang', type: 'nominal', title: null, scale: { domain: ['pure Python', 'numpy', 'C'], range: ['#f59e0b', '#3b82f6', '#22c55e'] } },
  },
};
const line = sample && {
  width: 700, height: 180,
  title: 'The first 3,000 synthetic ticks and their ' + py.w + '-tick moving average',
  data: { values: sample.price.flatMap((p, i) => [{ tick: i, value: p, series: 'price' }].concat(sample.ma[i] == null ? [] : [{ tick: i, value: sample.ma[i], series: 'moving average' }])) },
  mark: { type: 'line', strokeWidth: 1.2 },
  encoding: {
    x: { field: 'tick', type: 'quantitative' },
    y: { field: 'value', type: 'quantitative', scale: { zero: false }, title: 'price' },
    color: { field: 'series', type: 'nominal', title: null, scale: { range: ['#94a3b8', '#f59e0b'] } },
  },
};
// vconcat charts can't stretch to the cell's width, so they get a fixed one
return { $schema: 'https://vega.github.io/schema/vega-lite/v5.json', vconcat: line ? [bars, line] : [bars] };
